CREATE TABLE IF NOT EXISTS ui_state (id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY,state TEXT NOT NULL,spec TEXT NOT NULL,payload TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS commands (id TEXT PRIMARY KEY,fingerprint TEXT NOT NULL,run_id TEXT NOT NULL REFERENCES runs(id));
CREATE TABLE IF NOT EXISTS events (run_id TEXT NOT NULL REFERENCES runs(id),seq INTEGER NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(run_id,seq));
